"use strict";

const exec = require("child_process").exec;
const fs = require("fs");

// COMMON

const common = require("./apply_common");
const syslog = common.syslog();

// MODULE

function doFilesystem(extract_dir, filesystem_dir, callback) {
    let filepath = extract_dir + "/filesystem.tar.bz2";
    fs.access(filepath, fs.R_OK, function(error) {
        if (!error) {
            common.cleanScratchDir(filesystem_dir, function() {
                common.makeScratchDir(filesystem_dir, function() {
                    syslog.debug("Extract filesystem...");
                    exec("tar -C " + filesystem_dir + " -xf " + filepath, function(error, stdout, stderr) {
                        if (error) {
                            common.fail(error);
                        } else {
                            callback();
                        }
                    });
                });
            });
        } else {
            syslog.debug("filesystem.tar.bz2 not found");
            callback();
        }
    });
}

function doSkillInstall(source, subsystem, destination) {
    syslog.debug("Do skill install...");
    const extract_dir = common.extractDir(subsystem, "skills");
    common.writeWorkState("apply", function() {
        common.unpackUpdate(extract_dir, source, function() {
            common.doScript(extract_dir, "./preinstall", function() {
                doFilesystem(extract_dir, destination, function() {
                    common.doScript(extract_dir, "./postinstall", function() {
                        common.cleanScratchDir(extract_dir, function() {
                            common.writeWorkState("verify", function() {
                                syslog.info("Skill install completed!");
                                common.finalizeInstall();
                            });
                        });
                    });
                });
            });
        });
    });
}

function retrySkillUpdate(subsystem, from_version, destination, filter) {
    syslog.info("Retry %s update from %s", subsystem, from_version);
    common.waitForWifiLink(120, function(error) {
        if (error) {
            common.fail(error);
        } else {
            common.getAvailableUpdate(subsystem, from_version, filter, 
                function(update, tarball) {
                    doSkillInstall(tarball, subsystem, destination);
                });
        }
    });
}

function doSkillVerify() {
    //common.finalizeInstall();
}

function executeStep(step, work_state, gui) {
    const ws = work_state.current();
    const apply_time_est = common.bunzip2Estimate(ws.size);
    const backgrounds = [
        {
            first:  __dirname + "/Installer4.png",
            second: __dirname + "/Installer4a.png"
        },
        {
            first:  __dirname + "/Installer5.png",
            second: __dirname + "/Installer5a.png"
        },
        {
            first:  __dirname + "/Installer6.png",
            second: __dirname + "/Installer6a.png"
        }
    ];
    // compute backgrounds to use based on the index of the update
    const background_index = work_state.idx % backgrounds.length;
    const first_background = backgrounds[background_index].first;
    const second_background = backgrounds[background_index].second;
    if (step == "verify") {
        doSkillVerify();
    } else if (step == "retry") {
        gui.setBackground(second_background);
        gui.setPercent(0);
        gui.incrementTo(1.0, 30.0 + (2.0 * apply_time_est));
        retrySkillUpdate(ws.subsystem, ws.from, ws.destination, ws.filter);
    } else {
        gui.setBackground(first_background);
        gui.setPercent(0);
        gui.incrementTo(1.0, apply_time_est);
        doSkillInstall(ws.source, ws.subsystem, ws.destination);
    }
}

module.exports = {
    handlesSubsystem: function(subsystem) {
        // XXX do better...
        return subsystem != "bootloader" && subsystem != "os" && subsystem != "services";
    },
    execute: executeStep
}
